∀ {P A D : Type} [inst : DecidableEq.{1} P] [inst_1 : DecidableEq.{1} A] [inst_2 : DecidableEq.{1} D]
  [inst_3 : Fintype.{0} P] [inst_4 : Fintype.{0} A] [inst_5 : Fintype.{0} D]
  (shared : DefiKernel.Interleaving.Result P A D) (first second : DefiKernel.Parallel.Result P A D),
  @Eq.{1} Bool (@DefiKernel.Interleaving.matchesParallel P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 shared first)
      Bool.true →
    @DefiKernel.Parallel.ObservationallyEquivalent P A D first second →
      @Eq.{1} Bool
        (@DefiKernel.Interleaving.matchesParallel P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 shared second) Bool.true

∀ {P A D : Type} [inst : DecidableEq.{1} P] [inst_1 : DecidableEq.{1} A] [inst_2 : DecidableEq.{1} D]
  [inst_3 : Fintype.{0} P] [inst_4 : Fintype.{0} A] [inst_5 : Fintype.{0} D] (cfg : DefiKernel.Composition.Config P A D)
  (boundaries : DefiKernel.Parallel.ParallelBoundary P A D) (initial : DefiKernel.Composition.World P A D)
  (left right : DefiKernel.Parallel.Branch P A D) (lf rf : DefiKernel.Parallel.Footprint P A D),
  @Eq.{1}
      (Except.{0, 0} (DefiKernel.Parallel.AdmissionFailure P A D)
        (Prod.{0, 0} (DefiKernel.Parallel.Footprint P A D) (DefiKernel.Parallel.Footprint P A D)))
      (@DefiKernel.Parallel.admit P A D inst inst_1 inst_2 cfg boundaries left right)
      (@Except.ok.{0, 0} (DefiKernel.Parallel.AdmissionFailure P A D)
        (Prod.{0, 0} (DefiKernel.Parallel.Footprint P A D) (DefiKernel.Parallel.Footprint P A D))
        (@Prod.mk.{0, 0} (DefiKernel.Parallel.Footprint P A D) (DefiKernel.Parallel.Footprint P A D) lf rf)) →
    ∀ (schedule : DefiKernel.Interleaving.Schedule),
      @DefiKernel.Interleaving.Complete P A D left right schedule →
        have l :=
          @DefiKernel.Parallel.runBranch P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 cfg
            (boundaries DefiKernel.Parallel.BranchId.left) initial left;
        have r :=
          @DefiKernel.Parallel.runBranch P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 cfg
            (boundaries DefiKernel.Parallel.BranchId.right) initial right;
        @DefiKernel.Interleaving.ProjectedEquivalent P A D
          (@DefiKernel.Interleaving.runPrefix P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 cfg boundaries initial left
            right schedule)
          (@DefiKernel.Parallel.Joined.mk P A D
            (@DefiKernel.Parallel.mergeWorld P A D inst inst_1 inst_2 lf rf initial
              (@DefiKernel.Composition.Cursor.world P A D l) (@DefiKernel.Composition.Cursor.world P A D r))
            l r)

∀ {P A D : Type} {inst : DecidableEq.{1} P} [inst_1 : DecidableEq.{1} P] {inst_2 : DecidableEq.{1} A}
  [inst_3 : DecidableEq.{1} A] {inst_4 : DecidableEq.{1} D} [inst_5 : DecidableEq.{1} D]
  (pre pre_1 : DefiKernel.Composition.World P A D),
  @Eq.{1} (DefiKernel.Composition.World P A D) pre pre_1 →
    ∀ (boundary boundary_1 : DefiKernel.Composition.Boundary P A D),
      @Eq.{1} (DefiKernel.Composition.Boundary P A D) boundary boundary_1 →
        ∀ (receipt receipt_1 : DefiKernel.Composition.Receipt P A D),
          @Eq.{1} (DefiKernel.Composition.Receipt P A D) receipt receipt_1 →
            @Eq.{1} Prop (@DefiKernel.Composition.ReceiptAuthorized P A D inst inst_2 inst_4 pre boundary receipt)
              (@DefiKernel.Composition.ReceiptAuthorized P A D inst_1 inst_3 inst_5 pre_1 boundary_1 receipt_1)

theorems.source_statement:
theorem AdvanceSound.accounting {cfg : Config P A D} {boundaries : ParallelBoundary P A D}
    {left right : Branch P A D} {m post : Machine P A D} {b : BranchId}
    (h : AdvanceSound cfg boundaries left right m b post) (d : D) (a : A) :
    total post.world.state d a - total m.world.state d a = post.supply d a - m.supply d a

theorem AdvanceSound.active_index {cfg : Config P A D}
    {boundaries : ParallelBoundary P A D} {left right : Branch P A D}
    {m post : Machine P A D} {b : BranchId}
    (step : AdvanceSound cfg boundaries left right m b post)
    (previous : ∀ own, (m.local own).failure = none →
      (m.local own).nextIndex = min (m.local own).consumed
        (selectBranch left right own).length) :
    ∀ own, (post.local own).failure = none →
      (post.local own).nextIndex = min (post.local own).consumed
        (selectBranch left right own).length

